  function automatic real static_curve(input real xin);
    integer lo, hi, mid;
    real xc;
    begin
      if (!lut_loaded) load_lut();
      xc = (xin < LUT_X[0]) ? LUT_X[0] : ((xin > LUT_X[400]) ? LUT_X[400] : xin);
      lo = 0;
      hi = 400;
      while (hi - lo > 1) begin
        mid = (lo + hi) / 2;
        if (xc < LUT_X[mid]) hi = mid; else lo = mid;
      end
      static_curve = (LUT_X[hi] == LUT_X[lo])
                   ? LUT_Y[lo]
                   : LUT_Y[lo] + (LUT_Y[hi]-LUT_Y[lo]) * (xc-LUT_X[lo]) / (LUT_X[hi]-LUT_X[lo]);
    end
  endfunction

  real x, yv;
  bit  primed;
  // At DC the state settles to f/wp, which makes
  // y = FF*f + BX*f/wp = f*(wp/wz + 1 - wp/wz) = f. Starting there
  // means the model opens at its own operating point rather than
  // slewing to it through the first decade of the stimulus.
  initial begin
    x  = static_curve(DC_BIAS) / WP_0;
    yv = static_curve(DC_BIAS);
    primed = 1'b0;
  end

  always #(TSTEP) begin : wiener_step
    real dt, f, k1, k2, k3, k4;
    dt = DT_SECONDS;
    f  = static_curve(in_val);
    // Same reason as the scheduled form: open at the DC solution
    // for the stimulus's OWN starting value, which is what SPICE's
    // t=0 operating point solves for.
    if (!primed) begin
      x = f / WP_0;
      primed = 1'b1;
    end
    k1 = -WP_0*x + f;
    k2 = -WP_0*(x + 0.5*dt*k1) + f;
    k3 = -WP_0*(x + 0.5*dt*k2) + f;
    k4 = -WP_0*(x + dt*k3) + f;
    x  = x + (dt/6.0)*(k1 + 2.0*k2 + 2.0*k3 + k4);
    yv = FF_0*f + BX_0*x;
    out_val__d = yv;
  end


`ifndef SPICE2RNM_NO_ASSERT
  //--------------------------------------------------------------------
  // Validity domain, from the measurements that built this model.
  //
  // These state where the evidence applies. Outside it the model does
  // not extrapolate -- it CLAMPS, and keeps returning a plausible
  // number -- so being told once is the difference between a wrong
  // answer you can see and one you cannot.
  //
  // Compile out with +define+SPICE2RNM_NO_ASSERT.
  //--------------------------------------------------------------------
  localparam real DOMAIN_LO  = 0.0;
  localparam real DOMAIN_HI  = 3.54564;
  localparam real DOMAIN_EPS = 0.0709128; // 2% of the span, see model_assertions.py
  bit domain_reported = 1'b0;

  always @(in_val) begin : domain_check
    a_input_domain: assert (in_val >= DOMAIN_LO - DOMAIN_EPS && in_val <= DOMAIN_HI + DOMAIN_EPS)
    else if (!domain_reported) begin
      domain_reported = 1'b1;
      $warning("%m: input %0.6g V is outside the characterized range %0.6g..%0.6g V. static_curve clamps there, so this model keeps running and returns the endpoint value -- it is not extrapolating, and it is no longer evidence. Reported once.",
               in_val, DOMAIN_LO, DOMAIN_HI);
    end
  end

  bit nan_reported = 1'b0;

  always @(out_val) begin : output_health
    // NaN is the one value that is not equal to itself.
    a_output_finite: assert (out_val == out_val)
    else if (!nan_reported) begin
      nan_reported = 1'b1;
      $error("%m: output is NaN -- the integration diverged. Reported once.");
    end
  end
`endif

endmodule
